// Die drei Kern-Ideen der C++-Lösung:

// 1. if/else-Kette statt Wörterbuch:
if (wahl == "+")      ergebnis = addiere(a, b);
else if (wahl == "-") ergebnis = subtrahiere(a, b);

// 2. Sichere Zahleneingabe mit cin.fail():
double zahl_einlesen(const std::string& prompt) {
    double wert;
    while (true) {
        std::cout << prompt;
        std::cin >> wert;
        if (!std::cin.fail()) return wert;
        std::cin.clear();               // Fehlerzustand löschen
        std::cin.ignore(10000, '\n');   // Rest verwerfen
    }
}

