// C++-Details, die man beim Vergleichen lernt:
//
// 1. Schöne Ausgabe:
#include <iomanip>
std::cout << std::setprecision(2) << 10.0 / 3;  // 3.3

// 2. Modulo mit Kommazahlen:
#include <cmath>
double rest = std::fmod(10.5, 3.0);   // 1.5
// (Python: 10.5 % 3.0  ->  1.5 automatisch)

// 3. Python-Wörterbuch als C++:
#include <map>
#include <functional>
std::map<std::string, std::function<double(double, double)>> ops;
ops["+"] = addiere;
// ... fortgeschritten, aber das ist das gleiche Muster!

