#include <iostream>

double addiere(double a, double b) {
    return a + b;
}

double subtrahiere(double a, double b) {
    return a - b;
}

double multipliziere(double a, double b) {
    return a * b;
}

double dividiere(double a, double b) {
    return a / b;
}

int main() {
    const double a = 12.0;
    const double b = 4.0;

    std::cout << addiere(a, b) << std::endl;
    std::cout << subtrahiere(a, b) << std::endl;
    std::cout << multipliziere(a, b) << std::endl;
    std::cout << dividiere(a, b) << std::endl;

    return 0;
}

#include <iostream>
#include <stdexcept>

double teile(double a, double b) {
    if (b == 0.0) {
        throw std::runtime_error("Division durch 0 ist nicht erlaubt");
    }
    return a / b;
}

int main() {
    try {
        std::cout << teile(10.0, 2.0) << std::endl;
        std::cout << teile(5.0, 0.0) << std::endl;   // wirft
    } catch (const std::exception& fehler) {
        std::cerr << "Fehler: " << fehler.what() << std::endl;
    }

    std::cout << "Programm laeuft weiter" << std::endl;
    return 0;
}

#include <iostream>
#include <string>

double zahl_einlesen(const std::string& frage) {
    double wert = 0.0;
    while (true) {
        std::cout << frage;
        std::cin >> wert;
        if (!std::cin.fail()) {
            return wert;
        }
        std::cin.clear();                // Fehlerzustand loeschen
        std::cin.ignore(10000, '\n');    // Rest der Zeile verwerfen
        std::cout << "Das war keine Zahl" << std::endl;
    }
}

int main() {
    const double a = zahl_einlesen("Erste Zahl: ");
    const double b = zahl_einlesen("Zweite Zahl: ");
    std::cout << "Summe: " << (a + b) << std::endl;
    return 0;
}

#include <iostream>
#include <string>
#include <vector>

int main() {
    std::vector<std::string> verlauf;

    for (int i = 1; i <= 25; ++i) {
        verlauf.push_back("Rechnung " + std::to_string(i));
        if (verlauf.size() > 20) {
            verlauf.erase(verlauf.begin());   // aeltesten Eintrag loeschen
        }
    }

    std::cout << verlauf.size() << std::endl;
    std::cout << verlauf.front() << std::endl;
    std::cout << verlauf.back() << std::endl;

    return 0;
}

