    std::cout << std::fixed;
    std::cout << std::setprecision(2) << 10.0 / 3.0 << std::endl;
    std::cout << std::setprecision(1) << std::fmod(10.5, 3.0) << std::endl;
    std::cout << std::setprecision(0) << std::fmod(10.0, 4.0) << std::endl;
    return 0;
}

#include <functional>
#include <iostream>
#include <map>
#include <string>

double addiere(double a, double b) {
    return a + b;
}

double multipliziere(double a, double b) {
    return a * b;
}

int main() {
    std::map<std::string, std::function<double(double, double)>> ops;
    ops["+"] = addiere;
    ops["*"] = multipliziere;

    std::cout << ops["+"](6.0, 7.0) << std::endl;
    std::cout << ops["*"](6.0, 7.0) << std::endl;

    auto treffer = ops.find("/");
    if (treffer == ops.end()) {
        std::cout << "unbekannt" << std::endl;
    }

    return 0;
}
